-- 운영관리 enum 표: 드롭다운 선택지를 DB 에서 관리한다 (관리자 화면에서 수정).
create table enum_sets (
    id          bigint generated by default as identity primary key,
    set_code    varchar(60)  not null,
    set_name    varchar(100) not null,
    description text,
    sort_order  integer      not null default 0,
    created_at  timestamptz  not null default now(),
    updated_at  timestamptz  not null default now(),
    constraint uk_enum_sets_code unique (set_code)
);

-- 값을 묶는 분류 (예: 계약 상태의 초안 / 부서장 승인 / 검토 ...)
create table enum_groups (
    id         bigint generated by default as identity primary key,
    set_id     bigint       not null references enum_sets (id),
    group_code varchar(80)  not null,
    group_name varchar(100) not null,
    sort_order integer      not null default 0,
    constraint uk_enum_groups_set_code unique (set_id, group_code)
);

create table enum_values (
    id          bigint generated by default as identity primary key,
    set_id      bigint       not null references enum_sets (id),
    group_id    bigint references enum_groups (id),
    value_code  varchar(60)  not null,
    const_name  varchar(120),
    label       varchar(200) not null,
    remark      text,
    sort_order  integer      not null default 0,
    is_active   boolean      not null default true,
    created_at  timestamptz  not null default now(),
    updated_at  timestamptz  not null default now(),
    constraint uk_enum_values_set_code unique (set_id, value_code)
);
create index idx_enum_values_set_sort on enum_values (set_id, sort_order);

